## Media Processing Pipeline

### Basic Transcoding

```xiom
use xiom.ffmpeg;

fn main() -> Int {
  // Open input file
  let input = ffmpeg::Input::open("input.mp4")?;

  // Set up output
  let mut output = ffmpeg::Output::new("output.webm")
    .video_codec("libvpx-vp9")
    .audio_codec("libopus")
    .video_bitrate(1_000_000)  // 1 Mbps
    .audio_bitrate(128_000)    // 128 kbps
    .resolution(1920, 1080)
    .framerate(30);

  // Transcode
  let progress = input.transcode(&mut output)?;
  io.println("Transcoded: " + progress.frames.to_str() + " frames");
  return 0;
}
```

### Video Information

```xiom
let info = ffmpeg::probe("video.mp4")?;
io.println("Duration: " + info.duration.to_str() + "s");
io.println("Resolution: " + info.width.to_str() + "x" + info.height.to_str());
io.println("Codec: " + info.video_codec);
io.println("Bitrate: " + info.bitrate.to_str() + " bps");

for stream in info.streams {
  io.println(stream.codec_type.to_str() + ": " + stream.codec_name);
}
```

### Extracting Frames

```xiom
fn extract_thumbnail(input: &Str, output: &Str, time: Float64) -> Result<(), Error> {
  let frame = ffmpeg::Input::open(input)?
    .seek(time)?
    .read_frame()?;

  ffmpeg::Image::encode(frame, output, ImageFormat::Jpeg)?;
  Ok(())
}
```

### Video Filters

```xiom
// Apply filters
output.video_filter("scale=1280:720");        // Resize
output.video_filter("crop=640:480:100:50");    // Crop
output.video_filter("fps=24");                 // Change framerate
output.video_filter("hflip");                  // Horizontal flip
output.video_filter("drawtext=text='XIOM':x=10:y=10:fontsize=24:fontcolor=white");

// Complex filter graph
let filter_graph = ffmpeg::FilterGraph::new()
  .input("0:v")   // Video stream
  .input("1:v")   // Overlay
  .filter("[0:v][1:v]overlay=10:10[out]")
  .output("[out]");
```

### Audio Processing

```xiom
// Extract audio
ffmpeg::Input::open("video.mp4")?
  .output(ffmpeg::Output::new("audio.mp3")
    .audio_codec("libmp3lame")
    .no_video())
  .transcode()?;

// Normalize volume
output.audio_filter("volume=0.5");          // Half volume
output.audio_filter("loudnorm");            // EBU R128 normalization
```

### Streaming

```xiom
// RTMP stream to platform
ffmpeg::Input::open("screen_capture")?    // Or: "camera", "microphone"
  .output(ffmpeg::Output::new("rtmp://live.twitch.tv/app/stream_key")
    .format("flv")
    .video_codec("libx264")
    .preset("veryfast"))
  .stream()?;
```

